UPDATE notes
SET title = (
      SELECT scopes.scope || CASE CAST(substr(notes.note_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'public assetsverify' WHEN 2 THEN 'internalauthorizationtranslatedtranslated' ELSE 'sourcekey chainscheduleinspect' END
      FROM scopes WHERE scopes.n=CAST((CAST(substr(notes.note_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    ),
    body = (
      SELECT scopes.scope || CASE CAST(substr(notes.note_id,-4) AS INTEGER) % 3
        WHEN 1 THEN 'imagestranslated retain originaltranslatedreleasekey chaintranslatedand can seewatermark；commercialtranslatedstillmustverifyallow can range。'
        WHEN 2 THEN 'materialstranslatedtranslatedbrandinternalcommunication，onlytranslatedtoalreadytranslatedtranslatedrecipienttranslatedtranslated，cannottranslatedplatform can savedtranslatedpublic。'
        ELSE 'screenshot absent losecompletetranslatedtranslatedandauthorizationkey chain，only can internalthantranslatedtranslatedtranslated，must notenterlivestreamtranslatedtranslated。'
      END || ' currenttranslatedtranslated：' || scopes.constraint_fact || '。'
      FROM scopes WHERE scopes.n=CAST((CAST(substr(notes.note_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    ),
    image_captions = (
      SELECT '["' || scopes.scope || CASE CAST(substr(notes.note_id,-4) AS INTEGER) % 3 WHEN 1 THEN 'publicsourcescreenshot' WHEN 2 THEN 'internalauthorizationscreenshot' ELSE 'sourceawaitingtranslatedscreenshot' END || '","' || scopes.constraint_fact || '"]'
      FROM scopes WHERE scopes.n=CAST((CAST(substr(notes.note_id,-4) AS INTEGER)+2)/3 AS INTEGER)
    ),
    tags = CASE CAST(substr(note_id,-4) AS INTEGER) % 3 WHEN 1 THEN '["public livestream room","publicsource","watermark"]' WHEN 2 THEN '["public livestream room","brandconfidentiality","translatedinternal"]' ELSE '["public livestream room","sourceawaitingtranslated"," not  can public"]' END
WHERE note_id GLOB 'note_[0-9][0-9][0-9][0-9]';
